-- Слои карты (M16): национальные парки, заповедник, пограничная полоса и зона.
--
-- Справочник для всех, в том числе гостей (как зоны правил): границы, главное о въезде, тарифы в МРП
-- (только со страниц тарифов самих парков), сайт и продажа билетов, первоисточник и дата проверки.
-- Границы парков — OpenStreetMap (© участники OpenStreetMap, ODbL), упрощены до ≈ 100 м; погранполоса и
-- погранзона построены от государственной границы (постановление Правительства РК № 356) и
-- приблизительны. Данные и как их пересобрать — supabase/data/areas.

create type public.map_area_kind as enum ('national_park', 'nature_reserve', 'border_strip', 'border_zone');

create table public.map_areas (
  id              text primary key check (id ~ '^[a-z0-9_]{2,40}$'),
  kind            public.map_area_kind not null,
  name_ru         text not null,
  name_kk         text not null,
  name_en         text not null,
  -- Главное: въезд, пропуск, рыбалка.
  info_ru         text not null,
  info_kk         text not null,
  info_en         text not null,
  -- Тарифы в МРП; null — не опубликованы на сайте парка (на карточке — «тариф на КПП»).
  fee_person_mrp  numeric(5, 2) check (fee_person_mrp >= 0),
  fee_car_mrp     numeric(5, 2) check (fee_car_mrp >= 0),
  fee_fishing_mrp numeric(5, 2) check (fee_fishing_mrp >= 0),
  website_url     text check (website_url ~ '^https://'),
  tickets_url     text check (tickets_url ~ '^https://'),
  source_title    text not null,
  source_url      text check (source_url ~ '^https://'),
  verified_on     date not null,
  sort_order      integer not null default 100,
  geom            extensions.geometry(MultiPolygon, 4326) not null
);

create index map_areas_geom_idx on public.map_areas using gist (geom);

alter table public.map_areas enable row level security;
revoke all on table public.map_areas from anon, authenticated;
grant select on table public.map_areas to anon, authenticated;
create policy "map_areas: читать всем" on public.map_areas
  for select to anon, authenticated using (true);

-- МРП по годам: тарифы в МРП, в тенге — по значению текущего года.
create table public.mrp_values (
  year  integer primary key check (year between 2000 and 2100),
  tenge integer not null check (tenge > 0)
);

alter table public.mrp_values enable row level security;
revoke all on table public.mrp_values from anon, authenticated;
grant select on table public.mrp_values to anon, authenticated;
create policy "mrp_values: читать всем" on public.mrp_values
  for select to anon, authenticated using (true);

-- Закон о республиканском бюджете на 2026–2028 годы: МРП с 1 января 2026 года.
insert into public.mrp_values (year, tenge) values (2026, 4325);

