('almaty_reserve', 'nature_reserve', 'Алматинский заповедник', 'Алматы қорығы', 'Almaty Nature Reserve', 'Государственный природный заповедник: свободного посещения нет, рыбалка и охота запрещены. Пройти можно только с разрешения администрации заповедника.', 'Мемлекеттік табиғи қорық: еркін кіруге болмайды, балық және аң аулауға тыйым салынған. Тек қорық әкімшілігінің рұқсатымен кіруге болады.', 'State nature reserve: no free access, fishing and hunting are banned. Entry only with permission from the reserve administration.', null, null, null, null, null, 'Закон РК «Об особо охраняемых природных территориях» от 7 июля 2006 года № 175', 'https://adilet.zan.kz/rus/docs/Z060000175_', '2026-10-05', 20, extensions.st_geomfromtext('MULTIPOLYGON(((77.15037 43.12565,77.15714 43.11346,77.16309 43.10837,77.16682 43.10165,77.16427 43.09136,77.16579 43.08014,77.16301 43.0773,77.16629 43.07436,77.16737 43.07038,77.16686 43.06652,77.16326 43.06314,77.16091 43.0572,77.16081 43.04804,77.16245 43.04444,77.15813 43.03464,77.15923 43.03308,77.15708 43.02242,77.15992 43.01743,77.16956 43.0158,77.17251 43.01208,77.17545 43.0116,77.21566 43.02101,77.23307 43.01875,77.2343 43.01734,77.23415 43.01093,77.23943 43.01097,77.24539 43.00868,77.25647 43.00098,77.25492 42.99868,77.25458 42.98837,77.25909 42.98378,77.26425 42.98186,77.27072 42.97211,77.27751 42.97346,77.28307 42.9722,77.29109 42.97443,77.31424 42.97148,77.31988 42.97307,77.32438 42.97693,77.32677 42.9755,77.33389 42.97757,77.35553 42.97691,77.3774 42.97281,77.38797 42.97341,77.4049 42.98046,77.41279 42.99021,77.43037 43.00446,77.4331 43.00582,77.44147 43.00498,77.44522 43.00616,77.45892 43.01862,77.47358 43.01991,77.47772 43.0249,77.47182 43.03062,77.47139 43.03976,77.46696 43.04257,77.46525 43.04557,77.4557 43.05134,77.46024 43.05567,77.45636 43.06141,77.45048 43.06521,77.44853 43.07218,77.44319 43.07962,77.44387 43.08332,77.44849 43.08339,77.45015 43.08506,77.45063 43.08792,77.44661 43.09178,77.44736 43.09547,77.458 43.09833,77.